#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <iomanip>
using namespace std;

int main(){
vector<double>x={1,2,3,4,5,6},y={1,3,4,8,9,10};int window=4;
for(int start=0;start+window<=int(x.size());start++){
double mx=0,my=0,xx=0,xy=0;
for(int i=start;i<start+window;i++){mx+=x[i]/window;my+=y[i]/window;}
for(int i=start;i<start+window;i++){xx+=pow(x[i]-mx,2);xy+=(x[i]-mx)*(y[i]-my);}
cout<<start<<" "<<xy/xx<<"\n";
}
return 0;
}

